private static void addNameState(Set<SubRuleContext> candidateSubRuleIds, NameState nameState, Patterns pattern, Task task, int nextKeyIndex, final SubRuleContext.Generator subRuleContextGenerator) {
    // one of the matches might imply a rule match
    task.collectRules(candidateSubRuleIds, nameState, pattern, subRuleContextGenerator);
    moveFromWithPriorCandidates(candidateSubRuleIds, nameState, pattern, nextKeyIndex, task, subRuleContextGenerator);
}
